  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Down-14 Two-Point Conversion Protocol",
      "recommendation": "Attempt a two-point conversion immediately after scoring a touchdown when trailing by 14 points in the fourth quarter. If successful, the team trails by 6 points and can win on the next touchdown with a point-after kick; if unsuccessful, a second two-point attempt can still tie the game.",
      "rationale": "Published win-probability models demonstrate that attempting the two-point conversion on the first touchdown maximizes regulation win probability compared to kicking two extra points, which defaults the game to an equal-odds overtime.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.35,
          "interval_95_low": 0.05,
          "interval_95_high": 0.65,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "Public analytics provides clear empirical limits on two-point conversion rates, leading to a symmetric distribution around the expected win-probability gain."
        },
        "parameters": {
          "mu": 0.35,
          "sigma": 0.153,
          "conversion_note": "Calculated for normal distribution: mu = 0.35; sigma = (interval_95_high - interval_95_low) / 3.92 = (0.65 - 0.05) / 3.92 ≈ 0.153."
        },
        "consistency_check": "Confirmed that most_plausible_value (0.35) lies inside [0.05, 0.65] and support covers signed real values."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "Neutral-State Early-Down Passing Bias",
      "recommendation": "Increase 1st & 10 pass rate to at least 65% in neutral game states (win probability between 20% and 80%) across the first three quarters. Focus on short-to-intermediate high-completion concepts and play-action sequences to consistently move into second-and-manageable.",
      "rationale": "Expected Points Added (EPA) models consistently show that early-down passing generates higher EPA per play than early-down rushing, significantly reducing the frequency of third-and-long situations.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.75,
          "interval_95_low": 0.15,
          "interval_95_high": 1.35,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The large sample of public EPA play-by-play data allows for a symmetric normal distribution centered on established analytical estimates."
        },
        "parameters": {
          "mu": 0.75,
          "sigma": 0.306,
          "conversion_note": "Calculated for normal distribution: mu = 0.75; sigma = (interval_95_high - interval_95_low) / 3.92 = (1.35 - 0.15) / 3.92 ≈ 0.306."
        },
        "consistency_check": "Confirmed that most_plausible_value (0.75) lies inside [0.15, 1.35] and support covers signed real values."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Two-High Safety Shell Against Heavy Personnel",
      "recommendation": "Maintain a two-high safety shell (Cover 4 / Cover 6) on early downs even when the opponent deploys heavy personnel groupings (12 or 22 personnel). Accept a light box against the run to prioritize eliminating explosive passing plays over the top.",
      "rationale": "Analytics models establish that preventing passing explosives yields far higher expected points saved than defending against incremental rushing gains, making light-box run concessions mathematically favorable.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.4,
          "interval_95_low": -0.4,
          "interval_95_high": 1.2,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "A Student's t distribution with heavy tails accounts for extreme matchup failure cases against elite power-running offensive lines."
        },
        "parameters": {
          "nu": 4,
          "mu": 0.4,
          "sigma": 0.288,
          "conversion_note": "Calculated for student_t with nu = 4 degrees of freedom using critical value t_{0.975, 4} = 2.776: mu = 0.40; scale parameter sigma = (1.20 - (-0.40)) / (2 * 2.776) = 1.60 / 5.552 ≈ 0.288."
        },
        "consistency_check": "Confirmed that most_plausible_value (0.40) lies inside [-0.40, 1.20] and support covers signed real values."
      }
    },
    {
      "bucket": "intuition",
      "type": "game_management",
      "title": "End-of-Quarter Tempo Acceleration to Trap Personnel",
      "recommendation": "Shift to a rapid no-huddle pace with under 90 seconds remaining in the 1st and 3rd quarters while keeping the same offensive personnel. Lock tired or schematically unfavorable defensive personnel on the field across the quarter transition.",
      "rationale": "Public analytics models treat quarter breaks as neutral administrative resets and do not model fatigue accumulation across quarter transitions. Coaching intuition indicates that forcing exhausted defensive personnel to stay on the field across quarter breaks creates mental miscommunications and physical mismatches.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.25,
          "interval_95_low": -0.2,
          "interval_95_high": 0.9,
          "shape": "right_skewed",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "A right-skewed normal distribution models the asymmetrical upside of inducing a defensive bust or turnover against exhausted defender groups."
        },
        "parameters": {
          "xi": 0.02,
          "omega": 0.38,
          "alpha": 2.5,
          "conversion_note": "Fit numerically for skew_normal(xi, omega, alpha): location xi = 0.02, scale omega = 0.38, shape alpha = 2.5 yield a mode ≈ 0.25 and a central 95% interval covering [-0.20, 0.90]."
        },
        "consistency_check": "Confirmed that most_plausible_value (0.25) lies inside [-0.20, 0.90] and support covers signed real values."
      }
    },
    {
      "bucket": "intuition",
      "type": "offensive",
      "title": "Positionless Heavy-Personnel Spread Formations",
      "recommendation": "Deploy 13 personnel (1 RB, 3 TE, 1 WR) on 1st down but split all three tight ends wide in a 5-wide empty alignment. Force opposing linebackers and safeties into open-field coverage responsibilities against athletic tight ends.",
      "rationale": "Public analytics tracks personnel efficiency and formation width independently, remaining silent on the interaction effect of spreading heavy packages. Coaching intuition indicates that defensive personnel calls match offensive personnel, giving athletic tight ends clear spatial advantages against linebackers.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.45,
          "interval_95_low": -0.25,
          "interval_95_high": 1.45,
          "shape": "right_skewed",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "A right-skewed distribution captures the potential for explosive misdirection plays while accounting for occasional pass-protection breakdowns."
        },
        "parameters": {
          "xi": 0.15,
